OPENERS = {"en": ["Hi {name},", "Notes:", "From my journal:", "", "", ""],
           "de": ["Hallo {name},", "Notiz:", "Tagebuch:", "", "", ""],
           "nl": ["Hoi {name},", "Notitie:", "Uit mijn dagboek:", "", "", ""]}
DAYS = {"en": DAYS_EN, "de": DAYS_DE, "nl": DAYS_NL}


def filler(per_topic: int = 9, seed: int = 7) -> list:
    rng = random.Random(seed)
    out = []
    for lang, topics in TOPICS.items():
        for topic, sentences in topics.items():
            for i in range(per_topic):
                k = rng.randint(4, 6)
                picked = rng.sample(sentences, k)
                opener = rng.choice(OPENERS[lang])
                text = " ".join(([opener] if opener else []) + picked)
                text = text.replace("{name}", rng.choice(NAMES)).replace("{day}", rng.choice(DAYS[lang]))
                out.append((f"filler_{lang}_{topic}_{i}", lang, "filler", text))
    return out


