WITH = {"en": "{what} with {name}", "de": "{what} mit {name}", "nl": "{what} met {name}"}


def short_titles(seed: int = 11) -> list:
    """Each title once, and a third of them again with a name ("Kino mit Lotte"): about 125."""
    rng = random.Random(seed)
    out = []
    for lang, titles in SHORT.items():
        for i, title in enumerate(titles):
            out.append((f"short_{lang}_{i}", lang, "filler", title))
            if i % 3 == 0:
                out.append((f"short_{lang}_{i}_with", lang, "filler",
                            WITH[lang].format(what=title, name=rng.choice(NAMES))))
    return out
